const crypto = require('crypto');
const item = $input.first();
const input = item.json;
const headers = Object.fromEntries(Object.entries(input.headers || {}).map(([key, value]) => [key.toLowerCase(), value]));
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '').replace(/^sha256=/, '');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret || !/^\d{13}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 300000) {
  throw new Error('Webhook authentication failed: stale or missing timestamp');
}
// Verify the exact bytes Convex signed. Raw Body may be exposed as binary data.
let raw;
if (item.binary?.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else if (typeof input.body === 'string') {
  raw = input.body;
} else {
  throw new Error('Raw request body missing. Enable Raw Body on the Webhook node.');
}
if (!raw || Buffer.byteLength(raw, 'utf8') > 4096 || !/^[a-f0-9]{64}$/i.test(signature)) {
  throw new Error('Webhook authentication failed: invalid body or signature');
}
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) {
  throw new Error('Webhook authentication failed: HMAC mismatch');
}
const payload = JSON.parse(raw);
if (!payload.eventId || !payload.eventType || !payload.requestId || !payload.recipientLabel) throw new Error('Invalid notification event');
return [{ json: { eventId: String(payload.eventId), eventType: String(payload.eventType), toolName: String(payload.toolName || 'Tool'), recipientLabel: String(payload.recipientLabel), requestStatus: String(payload.requestStatus || '') } }];

const item = $input.first().json;
// Mock delivery deliberately logs no email, phone, user ID, loan dates, or auth tokens.
console.log('[LendLoop mock notification]', JSON.stringify({ eventId: item.eventId, type: item.eventType, to: item.recipientLabel, tool: item.toolName }));
return [{ json: { ok: true, eventId: item.eventId } }];
